var allLabels = $input.all().map(function(item) { return item.json; });
var emailData = $('Gmail Trigger').item.json;
var emailLabelIds = emailData.labelIds || [];
var isClienti = allLabels.some(function(label) {
  return emailLabelIds.includes(label.id) && label.name && label.name.toUpperCase().startsWith('CLIENTI');
});
var isPromotional = emailLabelIds.some(function(id) {
  return ['CATEGORY_PROMOTIONS', 'CATEGORY_SOCIAL'].includes(id);
});
var fromField = emailData.from;
var fromEmail = '';
if (fromField && typeof fromField === 'object' && fromField.value && fromField.value.length > 0) {
  fromEmail = (fromField.value[0].address || '').toLowerCase();
} else if (typeof fromField === 'string') {
  var match = fromField.match(/<([^>]+)>/);
  fromEmail = match ? match[1].toLowerCase() : fromField.toLowerCase();
}
var isSelfEmail = fromEmail === 'attilio.assirelli@gmail.com';
var collaboratorPatterns = [
  { pattern: 'ROSA ASSIRELLI', folder: 'ROSA ASSIRELLI' },
  { pattern: 'NICOLA MAROTTA', folder: 'Nicola Marotta' },
  { pattern: 'FRANCESCO DURANTI', folder: 'Francesco Duranti' },
  { pattern: 'LEGALADVICE', folder: 'LegalAdvice' }
];
var collaborator = null;
allLabels.forEach(function(label) {
  if (emailLabelIds.includes(label.id) && label.name) {
    var upperName = label.name.toUpperCase();
    collaboratorPatterns.forEach(function(cp) {
      if (upperName.includes(cp.pattern)) { collaborator = cp.folder; }
    });
  }
});
return [{ json: {
  isClientiEmail: isClienti, isPromotional: isPromotional, isSelfEmail: isSelfEmail,
  collaborator: collaborator, source: 'email', whatsappFrom: '', phoneNumberId: '',
  id: emailData.id || '', threadId: emailData.threadId || '',
  from: emailData.from || '', to: emailData.to || '',
  subject: emailData.subject || '', snippet: emailData.snippet || '',
  text: emailData.text || '', html: emailData.html || '',
  date: emailData.date || '', labelIds: emailData.labelIds || []
} }];

