  var m = cleaned.match(/\{[\s\S]*\}/);
  if (m) {
    parsed = JSON.parse(m[0]);
    topic = parsed.topic || 'GENERALE';
    if (parsed.keywords && parsed.keywords.length > 0) {
      keywords = parsed.keywords;
      driveQuery = parsed.keywords.map(function(k) {
        return "fullText contains '" + String(k).replace(/'/g, "\\'") + "'";
