var driveFolder = topicMap[topic] || topicMap.GENERALE;
if (!driveQuery) { driveQuery = driveFolder; }
var webSearchQuery = (keywords.length > 0 ? keywords.join(' ') : driveFolder) + ' normativa italiana';
var company = '';
var year = null;
var month = null;
try { company = parsed.company || ''; } catch(e) {}
try { year = parsed.year || null; } catch(e) {}
try { month = parsed.month || null; } catch(e) {}
