var emailData = $('Controlla Etichetta CLIENTI').item.json;
var html = String(emailData.html || '');
var plainText = String(emailData.text || '');

var links = [];
var linkPattern = /<a[^>]*href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi;
var match;
while ((match = linkPattern.exec(html)) !== null) {
  var url = match[1].trim();
  var text = match[2].replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();
  if (url.startsWith('http') && text.length > 2 && text.length < 200) {
    var urlLower = url.toLowerCase();
    if (!urlLower.includes('unsubscribe') && !urlLower.includes('disiscriv') && !urlLower.includes('tracking') && !urlLower.includes('pixel') && !urlLower.includes('utm_')) {
      links.push({ url: url, text: text });
    }
  }
}

var uniqueLinks = [];
var seenUrls = {};
links.forEach(function(l) { if (!seenUrls[l.url]) { seenUrls[l.url] = true; uniqueLinks.push(l); } });

var linksFormatted = uniqueLinks.slice(0, 25).map(function(l, i) {
  return '- [' + l.text + '](' + l.url + ')';
}).join('\n');

var contentForSummary = plainText || html.replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();

